// ===================== FLASHCARD DATA =====================
const fcData=[{"w":"La regla de oro, aplicada a la revisión con método","a":"✂️ Ninguna herramienta de esta etapa se cita sin autor y año. El primer borrador malo es de Lamott (1994); revisar es re-ver, de Sommers (1980); matar a tus amados, de Quiller-Couch (1914); el lector de prueba, de Elbow (1973); la premisa, de Egri (1946); terminar cortando, de Murray (1973). Cada herramienta con su fecha de fabricación."},{"w":"El primer borrador es malo a propósito","a":"📝 Anne Lamott, «Bird by Bird» (1994): el permiso de escribir mal el primer borrador es lo que deja empezar a revisar; nadie saca bien la primera vez. Límite: es un manual de taller con voz de autora, no una medición."},{"w":"Revisar es re-ver, no corregir palabras","a":"🔄 Nancy Sommers, «Revision Strategies of Student Writers and Experienced Adult Writers» (1980): el escritor con oficio revisa el sentido y la estructura; el novato solo cambia palabras sueltas. Editar no es revisar. Límite: es un estudio de didáctica, con muestra acotada."},{"w":"Matar a tus amados, y su mala atribución","a":"✂️ Arthur Quiller-Couch, conferencia de 1914, recogida en «On the Art of Writing» (1916): cortar lo que más te gusta si no sirve a la historia. MAL CITADO: se le atribuye a Faulkner, a Twain, a Wilde, a Chesterton; la dijo Quiller-Couch, y no hablaba de matar personajes, sino de revisar."},{"w":"El lector de prueba","a":"👀 Peter Elbow, «Writing Without Teachers» (1973): el lector útil no dice «me gustó»; dice qué le pasó al leer (dónde se perdió, dónde se aburrió, qué creía que iba a pasar). «Las películas de la mente del lector»."},{"w":"La premisa","a":"🏛️ Lajos Egri, «The Art of Dramatic Writing» (1946): toda historia tiene una premisa, una frase que es su columna, y toda escena la sirve o sobra. Es lo que se conserva al contar la historia en 30 segundos o en 30 minutos."},{"w":"Uno se termina cuando corta, no cuando añade","a":"🔚 Donald Murray, «The Maker's Eye: Revising Your Own Manuscripts» (1973): revisar el propio texto es leerse como un extraño frío; el borrador está terminado cuando ya no se puede quitar nada, no cuando ya no se puede añadir nada."},{"w":"La maldición del conocimiento","a":"🧠 Steven Pinker, «The Sense of Style» (2014): el que escribe ya sabe lo que quiso decir, así que no ve lo que falta en la página; es la causa principal de la prosa mala."},{"w":"La ilusión de profundidad explicativa","a":"🔬 Leonid Rozenblit y Frank Keil (2002): creemos entender, y haber explicado, mucho más de lo que de verdad podemos. Estatus: hallazgo replicado."},{"w":"La lista maestra de las once herramientas","a":"🗂️ Esta etapa recoge las once herramientas de las etapas anteriores, de la cadena y el hueco hasta contar sin la página, y las convierte en una sola lista de repaso para un borrador entero."},{"w":"La pasada de diagnóstico","a":"🔍 Pasar el borrador entero por la lista maestra y marcar cada escena donde algo falla, sin tocar nada todavía (Sommers, 1980). Diagnosticar antes de arreglar."},{"w":"La pasada del lector y el corte","a":"✂️ Dárselo a un lector de prueba y pedirle lo que le pasó (Elbow, 1973); cortar lo que el diagnóstico y el lector señalan, aunque duela (Quiller-Couch, 1914; Murray, 1973)."},{"w":"La prueba de dominio","a":"🎯 Contar la misma historia en 30 segundos, 3 minutos y 30 minutos. Si las tres no son la misma historia, la premisa no estaba clara (Egri, 1946)."},{"w":"Revisar contra editar (la grieta)","a":"🕳️ Se confunde revisar con corregir la ortografía y pulir frases. Revisar es RE-VER: volver a mirar la estructura, no maquillar la superficie. Editar es la superficie; revisar es la estructura."},{"w":"Las cinco etiquetas de estatus","a":"🏷️ Manual de taller con voz de autora (Lamott, Egri); estudio de didáctica de la escritura (Sommers); máxima de oficio mal atribuida (Quiller-Couch); método de taller (Elbow, Murray); y la etiqueta de la propia mente (Pinker; Rozenblit y Keil)."},{"w":"El cierre del Hilo y la puerta al Taller Mayor","a":"🚪 Esta etapa CIERRA la Ruta del Hilo que Tira, sus doce etapas completas, y abre la Ruta del Taller Mayor, que recorre entera, en ocho etapas, el oficio de revisar."}];
let fcIdx=0;
function upFC(){document.getElementById('fcInner').classList.remove('flipped');document.getElementById('fcW').textContent=fcData[fcIdx].w;document.getElementById('fcA').innerHTML=fcData[fcIdx].a;document.getElementById('fcCtr').textContent=(fcIdx+1)+' / '+fcData.length;}
function flipCard(){sfx('flip');document.getElementById('fcInner').classList.toggle('flipped');if(!xpTracker.fc.has(fcIdx)){xpTracker.fc.add(fcIdx);pts(1);}if(xpTracker.fc.size===fcData.length){fin('s-flash');unlockAchievement('flash_master');}}
function nextFC(){sfx('click');fcIdx=(fcIdx+1)%fcData.length;upFC();}
function prevFC(){sfx('click');fcIdx=(fcIdx-1+fcData.length)%fcData.length;upFC();}

