const qzData=[{"q":"Según Anne Lamott, «Bird by Bird» (1994), ¿qué se supone del primer borrador?","o":["a) Que se supone malo; ese permiso es lo que deja empezar a revisar","b) Que tiene que salir bien, o no vale la pena seguir","c) Que no hace falta escribirlo, se puede revisar directamente","d) Que lo debe escribir siempre un lector de prueba"],"c":0,"e":"El permiso de escribir mal el primer borrador es lo que deja empezar a revisar; nadie saca bien la primera vez."},{"q":"Según Nancy Sommers (1980), ¿qué distingue al escritor con oficio del novato al revisar?","o":["a) El novato revisa la estructura; el que tiene oficio solo cambia palabras","b) El que tiene oficio revisa el sentido y la estructura; el novato solo cambia palabras sueltas","c) Los dos hacen exactamente lo mismo","d) Ninguno de los dos revisa nunca la estructura"],"c":1,"e":"Revisar es re-ver la estructura, no corregir palabras; editar no es revisar."},{"q":"¿De quién es en verdad la frase «matar a tus amados» (murder your darlings)?","o":["a) De Arthur Quiller-Couch, en una conferencia de 1914","b) De William Faulkner","c) De Mark Twain","d) De Oscar Wilde"],"c":0,"e":"Se le atribuye a Faulkner, a Twain, a Wilde y a Chesterton; la dijo Quiller-Couch, y no hablaba de matar personajes, sino de revisar."},{"q":"Según Peter Elbow, «Writing Without Teachers» (1973), ¿qué debe reportar un lector de prueba útil?","o":["a) Si le gustó o no le gustó","b) Una calificación del uno al diez","c) Qué le PASÓ al leer: dónde se perdió, dónde se aburrió, qué creía que iba a pasar","d) Solo si recomendaría el texto a otros"],"c":2,"e":"El lector útil no dice «me gustó»; dice qué le pasó, las «películas de la mente del lector»."},{"q":"Según Lajos Egri, «The Art of Dramatic Writing» (1946), ¿qué es la premisa?","o":["a) El título de la obra","b) La primera escena de la historia","c) El nombre del protagonista","d) Una frase que es la columna de la historia, y que toda escena sirve o sobra"],"c":3,"e":"La premisa es lo que se conserva al contar la historia en 30 segundos o en 30 minutos."},{"q":"Según Donald Murray (1973), ¿cuándo está terminado un borrador?","o":["a) Cuando ya no se le ocurre a uno qué añadir","b) Cuando ya no se puede quitar nada más, no cuando ya no se puede añadir nada","c) Cuando lo aprueba un editor","d) Cuando pasa un número fijo de revisiones"],"c":1,"e":"Uno se termina cuando corta, no cuando añade; revisar es leerse como un extraño frío."},{"q":"¿Cuáles son las tres pasadas de la revisión con método, la herramienta de esta etapa?","o":["a) Título, música y cierre","b) Presupuesto, elenco y locación","c) Gancho, giro y objeción","d) Diagnóstico, lector y corte, prueba de dominio"],"c":3,"e":"Diagnóstico (Sommers, 1980); lector y corte (Elbow, 1973; Quiller-Couch, 1914; Murray, 1973); prueba de dominio (Egri, 1946)."},{"q":"¿Cuál es la grieta que esta etapa desarma?","o":["a) Creer que el primer borrador no existe","b) Creer que corregir la ortografía y pulir frases ya es revisar","c) Creer que la premisa nunca cambia","d) Creer que el lector de prueba siempre miente"],"c":1,"e":"Revisar es RE-VER la estructura; editar es la superficie, y son cosas distintas."},{"q":"¿En qué consiste la prueba de dominio?","o":["a) Contar la misma historia en 30 segundos, 3 minutos y 30 minutos, y que las tres sean la misma","b) Publicar el borrador sin revisarlo","c) Pedirle a diez lectores que voten si les gustó","d) Medir cuántas palabras tiene el borrador"],"c":0,"e":"Si las tres duraciones no cuentan la misma historia, la premisa no estaba clara (Egri, 1946)."},{"q":"¿Qué abre esta etapa, la duodécima y última de la Ruta del Hilo que Tira?","o":["a) La Ruta de la Cámara que Cuenta","b) La Ruta de Personas de Papel","c) La Ruta del Taller Mayor","d) La Ruta de la Pluma Afilada"],"c":2,"e":"Con esta etapa el Hilo queda completo, y se abre la Ruta del Taller Mayor, sobre el oficio de revisar."}];
let qzIdx=0,qzSel=-1,qzDone=false;
