const classifyTaskDB=[{"w":"El primer borrador malo","gen":"Manual de taller con voz de autora","n":"El permiso de escribir mal la primera vez","g":"Oficio de la escritura","t":"Lamott, 1994"},{"w":"Revisar es re-ver","gen":"Estudio de didáctica de la escritura","n":"Se re-ve la estructura, no se corrigen palabras","g":"Didáctica de la composición","t":"Sommers, 1980"},{"w":"Matar a tus amados","gen":"Máxima de oficio mal atribuida","n":"Cortar lo que gusta si no sirve a la historia","g":"Oficio de la escritura","t":"Quiller-Couch, 1914"},{"w":"El lector de prueba","gen":"Método de taller","n":"Reporta lo que le pasó, no su opinión","g":"Taller de escritura","t":"Elbow, 1973"},{"w":"La premisa","gen":"Manual de taller con voz de autora","n":"La columna que toda escena sirve o sobra","g":"Dramaturgia","t":"Egri, 1946"},{"w":"Terminar cortando","gen":"Método de taller","n":"Se termina cuando ya no se puede quitar nada","g":"Taller de escritura","t":"Murray, 1973"},{"w":"La maldición del conocimiento","gen":"Tesis de un autor sobre un fenómeno bien documentado","n":"Quien sabe algo no puede ver cómo se ve para quien no lo sabe","g":"Psicología cognitiva","t":"Pinker, 2014"},{"w":"La ilusión de profundidad explicativa","gen":"Hallazgo replicado","n":"Creemos haber explicado más de lo que podemos demostrar","g":"Psicología cognitiva","t":"Rozenblit y Keil, 2002"},{"w":"La revisión con método","gen":"Herramienta de la etapa","n":"Tres pasadas: diagnóstico, lector y corte, prueba de dominio","g":"Storytelling de esta casa","t":"Etapa 12"},{"w":"La lista maestra","gen":"Herramienta de la etapa","n":"Las once herramientas de la ruta, para un borrador entero","g":"Storytelling de esta casa","t":"Etapa 12"}];
