const explainQuestions=[{"q":"Explica el primer borrador malo, según Anne Lamott, «Bird by Bird» (1994), y por qué el permiso de escribir mal es lo que deja empezar a revisar.","ans":"Lamott sostiene, en «Bird by Bird» (1994), que el primer borrador se supone malo: nadie saca bien la primera vez, y creer lo contrario es lo que paraliza a quien escribe, porque cada frase se defiende como si tuviera que ser la definitiva. Darse permiso de escribir mal la primera vez es justo lo que permite avanzar hasta el final del borrador, y solo con el borrador completo delante se puede empezar la revisión de verdad. Su límite es que es la voz de una autora de taller, no una medición."},{"q":"Explica la diferencia entre revisar y editar, según Nancy Sommers (1980), y por qué corregir la ortografía no basta.","ans":"Sommers, en «Revision Strategies of Student Writers and Experienced Adult Writers» (1980), estudió cómo revisan los escritores con oficio frente a los que recién empiezan, y encontró que el escritor con oficio re-ve la estructura entera (si una escena gira, si el orden sirve, si sobra un personaje), mientras el novato solo cambia palabras sueltas, como corregir una falta de ortografía o mover una coma. Corregir la ortografía no basta porque deja intacto exactamente lo que hace falta re-ver: la estructura. Su límite es que es un estudio de didáctica con muestra acotada, no una ley universal."},{"q":"Explica la herramienta de esta etapa, la revisión con método, y cómo se aplicaría a un borrador real de la casa.","ans":"La revisión con método tiene tres pasadas: la de diagnóstico, pasar el borrador entero por la lista maestra de las once herramientas de la ruta y marcar dónde falla cada una, sin tocar nada todavía (Sommers, 1980); la del lector y el corte, dárselo a un lector de prueba y pedirle lo que le pasó, no su opinión (Elbow, 1973), y cortar lo que el diagnóstico y el lector señalan, aunque duela (Quiller-Couch, 1914; Murray, 1973); y la prueba de dominio, contar la misma historia en treinta segundos, en tres minutos y en treinta minutos, para comprobar que la premisa esté clara (Egri, 1946). Aplicada a un borrador real, exige marcarlo entero antes de tocar una coma, conseguir un lector que reporte hechos y no opiniones, y terminar contándolo en las tres duraciones."},{"q":"Explica la mala atribución de «matar a tus amados», y por qué esta casa la cita con cuidado.","ans":"«Murder your darlings», cortar lo que más te gusta si no sirve a la historia, se le atribuye con frecuencia a Faulkner, a Twain, a Wilde o a Chesterton, pero la dijo Arthur Quiller-Couch en una conferencia de 1914, recogida después en «On the Art of Writing» (1916). Además, Quiller-Couch no hablaba de matar personajes, como a veces se simplifica, sino de revisar: cortar la frase o la escena amada que el autor no quiere soltar aunque no sirva a la historia. Esta casa la cita con cuidado porque es exactamente el tipo de máxima famosa que circula sin comprobar su fuente, la misma trampa que ya se desarmó con Chéjov en la etapa 5."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.',"<strong>Ejemplo:</strong> Cortar lo que gusta si no sirve a la historia. → <span style=\"color:var(--jade);font-weight:700;\">Matar a tus amados (Quiller-Couch, 1914)</span>"]);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
