const evalTFBank=[{"q":"Según Lamott (1994), el primer borrador se supone malo.","a":true},{"q":"Lamott publica «Bird by Bird» en 1994.","a":true},{"q":"Revisar es corregir la ortografía y pulir un par de frases.","a":false},{"q":"Según Sommers (1980), el escritor con oficio revisa la estructura, no solo palabras sueltas.","a":true},{"q":"Sommers publica su estudio de revisión en 1980.","a":true},{"q":"«Matar a tus amados» lo dijo Faulkner, según la leyenda comprobada.","a":false},{"q":"La frase «matar a tus amados» es de Arthur Quiller-Couch, en una conferencia de 1914.","a":true},{"q":"Según Elbow (1973), el lector de prueba debe reportar su opinión, no lo que le pasó.","a":false},{"q":"El lector de prueba dice dónde se perdió, dónde se aburrió y qué creía que iba a pasar.","a":true},{"q":"Egri publica «The Art of Dramatic Writing» en 1946.","a":true},{"q":"Según Egri, la premisa cambia según la duración en que se cuenta la historia.","a":false},{"q":"Murray (1973) dice que uno se termina cuando corta, no cuando añade.","a":true},{"q":"Steven Pinker describe la maldición del conocimiento en «The Sense of Style» (2014).","a":true},{"q":"Rozenblit y Keil describieron la ilusión de profundidad explicativa en 2002.","a":true},{"q":"La prueba de dominio consiste en publicar el borrador sin revisarlo.","a":false}];
const evalMCBank=[{"q":"Según Lamott, «Bird by Bird» (1994), ¿qué se supone del primer borrador?","o":["a) Que tiene que salir bien siempre","b) Que no hace falta escribirlo","c) Que se supone malo, y ese permiso deja empezar a revisar","d) Que lo escribe siempre un lector de prueba"],"a":2},{"q":"Según Sommers (1980), ¿qué distingue a quien tiene oficio al revisar?","o":["a) Solo cambia palabras sueltas","b) No revisa nunca","c) Revisa la estructura entera, no solo palabras","d) Revisa exclusivamente la ortografía"],"a":2},{"q":"¿Quién dijo en verdad «matar a tus amados» (murder your darlings)?","o":["a) Arthur Quiller-Couch, en una conferencia de 1914","b) William Faulkner","c) Mark Twain","d) G. K. Chesterton"],"a":0},{"q":"Según Elbow (1973), ¿qué debe reportar un lector de prueba útil?","o":["a) Si le gustó o no","b) Qué le pasó al leer: dónde se perdió, dónde se aburrió","c) Una nota del uno al diez","d) Si lo recomendaría"],"a":1},{"q":"Según Egri, «The Art of Dramatic Writing» (1946), ¿qué es la premisa?","o":["a) La frase columna que toda escena sirve o sobra","b) El título de la historia","c) La primera escena","d) El nombre del protagonista"],"a":0},{"q":"Según Murray (1973), ¿cuándo está terminado un borrador?","o":["a) Cuando ya no se le ocurre a uno qué añadir","b) Cuando lo aprueba un editor","c) Cuando ya no se puede quitar nada más","d) Después de un número fijo de revisiones"],"a":2},{"q":"¿Cuáles son las tres pasadas de la revisión con método?","o":["a) Título, música y cierre","b) Presupuesto, elenco y locación","c) Diagnóstico, lector y corte, prueba de dominio","d) Gancho, giro y objeción"],"a":2},{"q":"¿Cuál es la grieta que esta etapa desarma?","o":["a) Creer que corregir la ortografía ya es revisar","b) Creer que el primer borrador no existe","c) Creer que la premisa nunca cambia","d) Creer que el lector de prueba siempre miente"],"a":0},{"q":"¿En qué consiste la prueba de dominio?","o":["a) Publicar sin revisar","b) Contar la misma historia en 30 segundos, 3 minutos y 30 minutos","c) Pedir que diez lectores voten si les gustó","d) Medir cuántas palabras tiene el borrador"],"a":1},{"q":"¿Qué abre esta etapa, la duodécima y última del Hilo?","o":["a) La Ruta de la Cámara que Cuenta","b) La Ruta del Taller Mayor","c) La Ruta de Personas de Papel","d) La Ruta de la Pluma Afilada"],"a":1},{"q":"¿Qué describe Steven Pinker (2014)?","o":["a) El efecto de superioridad de la imagen","b) La maldición del conocimiento","c) La composición oral","d) El montaje de choque"],"a":1},{"q":"¿Qué describen Rozenblit y Keil (2002)?","o":["a) La premisa dramática","b) La actio","c) El lector de prueba","d) La ilusión de profundidad explicativa"],"a":3},{"q":"¿Cuántas herramientas trae la lista maestra que esta etapa recoge?","o":["a) Once","b) Seis","c) Ocho","d) Tres"],"a":0},{"q":"¿Qué le falta a «el lector dijo que le gustó, ya está»?","o":["a) Nada, ya es una revisión completa","b) Le falta un premio literario","c) Le falta la opinión de un segundo lector","d) Le falta reportar qué le pasó de verdad al leer (Elbow, 1973)"],"a":3},{"q":"¿Cuál es el límite del manual de Lamott (1994)?","o":["a) Es una medición con corpus amplio","b) No tiene ningún límite","c) Solo aplica al cine","d) Es la voz de una autora de taller, no una medición"],"a":3}];
