// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1914","icon":"✂️","label":"Quiller-Couch y «matar a tus amados»","text":"Arthur Quiller-Couch, en una conferencia de 1914 (recogida en «On the Art of Writing», 1916), dice que hay que matar a tus amados: cortar lo que más gusta si no sirve a la historia. <strong>Por qué importa aquí:</strong> es la fuente más antigua de la etapa, y la más mal atribuida: se le adjudica a Faulkner, a Twain, a Wilde, a Chesterton."},{"y":"1946","icon":"🏛️","label":"Egri y la premisa","text":"Lajos Egri publica «The Art of Dramatic Writing»: toda historia tiene una premisa, una frase que es su columna, y toda escena la sirve o sobra. <strong>Por qué importa aquí:</strong> es la herramienta que sostiene la prueba de dominio: la premisa es lo que se conserva al contar la historia en 30 segundos o en 30 minutos."},{"y":"1973","icon":"👀","label":"Elbow y Murray, el lector de prueba y el corte final","text":"El mismo año, Peter Elbow publica «Writing Without Teachers» (el lector de prueba reporta lo que le pasó, no su opinión) y Donald Murray publica «The Maker's Eye» (uno se termina cuando corta, no cuando añade). <strong>Por qué importa aquí:</strong> son las dos herramientas que cierran la segunda pasada de la revisión con método."},{"y":"1980","icon":"🔄","label":"Sommers y revisar es re-ver","text":"Nancy Sommers publica «Revision Strategies of Student Writers and Experienced Adult Writers»: el escritor con oficio revisa la estructura; el novato solo cambia palabras. <strong>Por qué importa aquí:</strong> es la fuente que declara la grieta central de esta etapa: revisar no es corregir palabras."},{"y":"1994","icon":"📝","label":"Lamott y el primer borrador malo","text":"Anne Lamott publica «Bird by Bird»: el primer borrador se supone malo, y ese permiso es lo que deja empezar a revisar. <strong>Por qué importa aquí:</strong> es el punto de partida de toda la etapa: sin ese permiso, nadie llega a tener un borrador completo que revisar."},{"y":"2002","icon":"🔬","label":"Rozenblit y Keil y la ilusión de profundidad explicativa","text":"Leonid Rozenblit y Frank Keil describen la ilusión de profundidad explicativa: creemos entender, y haber explicado, mucho más de lo que en verdad podemos demostrar. <strong>Por qué importa aquí:</strong> explica, junto con Pinker (2014), por qué nadie ve solo su propio borrador."},{"y":"2014","icon":"🧠","label":"Pinker y la maldición del conocimiento","text":"Steven Pinker publica «The Sense of Style»: quien escribió ya sabe lo que quiso decir, y por eso no ve lo que falta en la página. <strong>Por qué importa aquí:</strong> es la razón, según Pinker, de la prosa mala en general, y la que justifica que el lector de fuera no sea un lujo."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: EL BORRADOR «REVISADO» SOLO EN LA ORTOGRAFÍA ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(seAplicaHerramienta){sfx(seAplicaHerramienta?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(seAplicaHerramienta){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">✂️</span><span class="ms-text"><strong>Se aplicó la revisión con método:</strong> se cortó la escena que no giraba nada, el lector de prueba confirmó dónde se perdía, y la prueba de dominio comprobó que la historia sobrevivía en treinta segundos.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📌</span><span class="ms-text"><strong>Quedó apuntada la razón del cambio:</strong> «que se entienda no basta: hay que re-ver, no corregir», para que la próxima vez no haga falta discutirlo desde cero.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📖</span><span class="ms-text"><strong>Se grabó tal cual:</strong> el guion se grabó con la escena que no giraba nada, y cuando alguien preguntó por qué el video se sentía largo, nadie en la casa supo qué responder.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✂️</span><span class="ms-text"><strong>Confundir «se entiende» con «ya se revisó»</strong> es exactamente el error que esta etapa señala: lo que distingue revisar de editar no es si el mensaje llega, es si se re-vio la estructura de verdad.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = La pasada de diagnóstico, paradoja =
// El lector de prueba, utilidad = La revisión con método, ruina = Corregir
// la ortografía y creer que se revisó.
const parteData={"esperado":{"nombre":"La pasada de diagnóstico","icon":"🔍","estructura":{"title":"Qué es","info":"• Pasar el borrador entero por la lista maestra de las once herramientas de la ruta<br>• Marcar dónde falla cada una, sin tocar nada todavía (Sommers, 1980)<br>• Es re-ver la estructura, no corregir palabras<br>• NO es lo mismo que corregir la ortografía, aunque se sienta como trabajo hecho"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿se marcó cada una de las once herramientas, una por una?<br>• Se compara con la lista maestra, herramienta por herramienta<br>• Se busca si el diagnóstico tocó la estructura, o solo palabras sueltas<br>• Se anota qué falla, sin corregir todavía nada"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que corregir la ortografía ya es diagnosticar<br>• En corregir sobre la marcha, sin terminar de marcar todo primero<br>• En saltarse alguna de las once herramientas de la lista maestra<br>• En diagnosticar sin fecha ni autor de la herramienta usada"},"cuidados":{"title":"En esta casa","info":"• Todo borrador de esta casa se marca entero antes de tocar una coma<br>• Se declara siempre «Sommers, 1980» al citar la pasada de diagnóstico<br>• Se usa como primer movimiento de la revisión con método<br>• Y se recuerda que diagnosticar bien no corrige nada todavía"}},"paradoja":{"nombre":"El lector de prueba","icon":"👀","estructura":{"title":"Qué es","info":"• Elbow (1973): el lector reporta lo que le PASÓ, no su opinión<br>• Dónde se perdió, dónde se aburrió, qué creía que iba a pasar, qué no entendió<br>• «Las películas de la mente del lector»<br>• NO es lo mismo que preguntar «¿te gustó?»"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿el lector reportó hechos concretos, o solo una opinión?<br>• Se busca si dijo dónde se perdió y dónde se aburrió<br>• Se compara con la revisión con método, segunda pasada<br>• Se comprueba si lo que dijo el lector sirvió para cortar algo"},"enfermedades":{"title":"Dónde se cae","info":"• En aceptar «me gustó» como si fuera un reporte<br>• En usar un solo lector y tratarlo como verdad absoluta<br>• En no pedirle las cuatro preguntas concretas<br>• En olvidar que no todo lector sabe reportar así (límite del método)"},"cuidados":{"title":"En esta casa","info":"• Todo borrador que va a publicarse pasa por al menos un lector de prueba<br>• Se declara siempre el año al citar a Elbow<br>• Se usa como segundo movimiento de la revisión con método<br>• Y se recuerda que el lector informa, no decide por el autor"}},"utilidad":{"nombre":"La revisión con método","icon":"✂️","estructura":{"title":"Qué es","info":"• La herramienta de esta etapa, en tres pasadas: diagnóstico, lector y corte, prueba de dominio<br>• Se apoya en las seis herramientas de la tabla madre, cada una con su autor y su año<br>• Se recuerda con Pinker (2014) y Rozenblit y Keil (2002): por qué nadie ve solo su propio borrador<br>• Si no aguanta las tres pasadas, todavía no está listo para publicarse"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta si se corrió el diagnóstico completo<br>• Se busca si un lector de prueba reportó algo concreto<br>• Se comprueba si la premisa sobrevive a la prueba de dominio<br>• Se anota en las tres pasadas, aunque a veces una quede pendiente"},"enfermedades":{"title":"Dónde se cae","info":"• En creer que basta con una de las tres pasadas<br>• En corregir la ortografía y llamar a eso revisión completa<br>• En saltarse la prueba de dominio por falta de tiempo<br>• En olvidar que diagnóstico, lector y prueba piden operaciones distintas"},"cuidados":{"title":"En esta casa","info":"• Todo borrador de esta casa se mide con las tres pasadas antes de publicarse<br>• Se declara siempre la herramienta que sostiene cada decisión<br>• Se usa como la prueba final antes de dar cualquier borrador por terminado<br>• Y se recuerda que ninguna pasada se salta"}},"ruina":{"nombre":"Corregir la ortografía y creer que se revisó","icon":"🚫","estructura":{"title":"Qué es","info":"• Corregir faltas de ortografía y pulir un par de frases, y llamar a eso «ya lo revisé»<br>• Es donde caen los borradores de la casa que llegan «listos» sin haber pasado la estructura<br>• No es lo mismo que usar la pasada de diagnóstico (Sommers, 1980) de verdad<br>• Es la otra cara de la revisión con método: donde el oficio termina y la superficie empieza"},"funcion":{"title":"Cómo se comprueba","info":"• Se pregunta: ¿esto se re-vio de verdad, o es un texto con la ortografía corregida?<br>• Se pregunta: ¿alguna escena sigue sin girar nada?<br>• Se compara con la revisión con método: ¿qué se corrigió tal cual, sin re-ver nada?<br>• Se decide si el borrador se cae, o aguanta, al pedirle la lista maestra completa"},"enfermedades":{"title":"Dónde se cae","info":"• En corregir la ortografía y detenerse ahí<br>• En pulir frases sin tocar la estructura entera<br>• En confiar en que «se entiende» sin correr ningún lector de prueba<br>• En olvidar que revisar y editar piden operaciones distintas"},"cuidados":{"title":"En esta casa","info":"• Todo borrador sospechoso, en esta casa, se marca de nuevo con la lista maestra<br>• Se pregunta siempre: ¿qué de esto se re-vio de verdad, y qué solo se corrigió?<br>• Se prefiere revisar de nuevo que dejar un borrador disfrazado de revisado<br>• Y se recuerda: la superficie no se confunde con la estructura"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

