/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con la entrevista
// y la conversación la etiqueta crece: además del pastiche hay que declarar que
// el encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={"borges":{"titulo":"El que nunca terminó el mismo cuento","tipo":"Cuento, a la manera de Jorge Luis Borges"},"cervantes":{"titulo":"La compañía que preguntó lo que informa","tipo":"Capítulo, a la manera de Miguel de Cervantes Saavedra"},"harari":{"titulo":"La especie que cree que ya se explicó","tipo":"Ensayo, a la manera de Yuval Noah Harari"},"entrevista":{"titulo":"Treinta y nueve finales","tipo":"Entrevista imaginada con Ernest Hemingway, a la manera de Joaquín Soler Serrano","ficcion":true},"gala":{"titulo":"La obra que nunca se da por acabada","tipo":"El Loco de la Colina: Jesús Quintero conversa con Juan Ramón Jiménez (conversación imaginada)","ficcion":true},"debate":{"titulo":"¿El taller de escritura mejora al escritor, o lo homogeniza?","tipo":"Careo: las dos posturas de una disputa abierta, con sus réplicas","careo":true}};
function _etiquetaImpresa(meta){
  if(meta&&meta.careo){
    return '<div class="etiqueta"><strong>✂️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Las personas citadas se mencionan en tercera persona como fuentes, <strong>toda obra, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.</div>';
  }
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
